import{z as s,x as p,o as t,c as A,q as r,j as n,D as e,d as E,s as l,S as i}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"物镜污染","description":"","frontmatter":{"title":"物镜污染","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/lens-contamination.md","filePath":"litho/lens-contamination.md","lastUpdated":1791063341000}'),B={name:"litho/lens-contamination.md"};function d(h,a,m,_,c,f){const o=p("Mermaid");return t(),A("div",null,[a[2]||(a[2]=r('<h1 id="物镜污染" tabindex="-1">物镜污染 <a class="header-anchor" href="#物镜污染" aria-label="Permalink to &quot;物镜污染&quot;">​</a></h1><div class="epigraph"><p>193 nm 把空气里的有机物打成膜，镀在镜头上：透过率掉、散射升、像差漂。污染是化学寿命，不是致密化。</p><footer>—— 对照 DUV 光学 carbon contamination；浸没末片的水痕与析出</footer></div><p><a href="/litho/birefringence-polarization">上一课</a>收束偏振。本课是物镜单元最后一课：表面脏。致密化在体里；污染在面上。下一单元工件台从机械另起。表面脏的另一面是它比体损伤快得多：致密化按月走，一张碳膜几周就能把透过率拉低百分之一级；但它可逆——脏能洗，致密化不能。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>净化空气仍有 ppb 级有机：光刻胶单体、轨道烘烤排气、真空泵油雾穿过末端 ULPA 之后仍留有 ppm 到 ppb 分压。193 nm 光子 6.4 eV，高于 C–H、C–C 键能（3–5 eV），直接光解这些分子；碎片在玻璃面吸附、交联成亚稳碳膜，生长速率正比于局部辐照度乘有机分压——所以膜先长在离掩模最近、辐照最强的前组。膜厚几十纳米就有三件事：透过率掉，剂量闭环把激光功率推上去，<a href="/litho/laser-gas-lifetime">激光气体寿命</a>被顺手偷走；膜厚不均匀是块楔形相位板，表现像慢变像差；表面散射把能量漏进杂散光。浸没末片还有水印、胶析出、气泡残骸：水膜把胶里低分子物浸出来，弯液面扫过处干燥成环。把透过率下降全写成气体寿命（激光），会去换错耗材——先查吹扫日志和有机源，再动激光。</p><p><span class="marginnote">数字实例：速率律 \\(r\\propto I\\cdot p_\\mathrm{org}\\) 意味着把有机分压从 1 ppb 压到 0.1 ppb，同样辐照下成膜速率约慢 10 倍——净化等级差一个数量级，镜头寿命差数倍，账就是这么算出来的。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>环境：化学过滤器（活性炭加离子交换介质两级）按压差与寿命更换，镜头吹扫用过滤干燥氮气保持微正压，密封圈老化与流量漂移进点检表。末片：浸没回收与清洗循环。监测：透过率/杂散光、定期像差——三条曲线互证才能分开「膜」与「体」。清洗有离线与在线限制，末片比内组容易够到：可拆卸、离线湿法清洗最干净；内组要开桶重新装调，停机成本与风险都高，而且过度清洗伤增透膜，清洗次数和剂量一样是有限资源。</p><p>与 <a href="/litho/flare-and-stray">杂散光 flare</a> 相关：脏是 flare 的时间函数，flare 的定期复查因此是污染的免费仪表。</p>',9)),(t(),n(i,null,{default:e(()=>[l(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ORG%5B%22%E6%9C%89%E6%9C%BA%20ppb%22%5D%20--%3E%20UV%5B%22193%20nm%20%E5%85%89%E8%A7%A3%22%5D%0A%20%20UV%20--%3E%20FILM%5B%22%E8%A1%A8%E9%9D%A2%E8%86%9C%22%5D%0A%20%20FILM%20--%3E%20T%5B%22%E9%80%8F%E8%BF%87%20%2F%20%E6%95%A3%E5%B0%84%22%5D%0A%20%20H2O%5B%22%E6%B5%B8%E6%B2%A1%E6%AE%8B%E7%95%99%22%5D%20--%3E%20FILM%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p><span class="marginnote">EUV 多层污染是氢与锡的另一套化学，见 EUV 课，不要把 DUV 碳膜和锡滴混名。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>光子打断挥发有机，碎片吸附聚合。自由基在表面停留期间交联，最终形成溶剂擦不掉的碳氢网络——清除要靠等离子体或专用化学，这是清洗配方难写的根源。薄膜改反射/吸收，也改有效波前：非均匀厚度等价于一块楔形相位板，进了像差计量就是「热模型解释不了的慢残差」。颗粒则是局域缺陷，计量上像 flare 热点，暗场复查可定位。速率律 \\(r\\propto I\\cdot p_\\mathrm{org}\\) 解释了两件事：净化等级差一个数量级、镜头寿命差数倍；以及闲置时关快门、缩短光路暴露时间，与换滤芯同样有效。颗粒沉积则与光化学膜不同源：颗粒走输运与静电吸附，不靠光子，吹扫挡不住，抓手换成环境与浸没水的颗粒过滤，两类污染分两条账治理。清洗之后还有一条隐藏账目：清洗会微弱改变元件面形与膜层，机台镜头文件要重新标定一次，否则清洗本身就变成一次像差台阶。</p><p><span class="marginnote">直觉类比：厚薄不均的碳膜像贴在镜头上一块肉眼难见的楔形玻璃，光穿过时被悄悄拐了角度——计量看到的不是「脏」，而是一颗「慢慢变歪」的镜头。</span></p><p><span class="marginnote">术语翻译：flare（杂散光）就是本该聚进图形的光被表面散射后漏到了别处，把本该暗的区域照亮。脏镜头让 flare 随时间单调上涨，所以定期复查 flare 曲线等于给污染装了一块免费仪表。</span></p>',5)),(t(),n(i,null,{default:e(()=>[l(o,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20FILM%5B%22%E5%85%89%E5%8C%96%E5%AD%A6%E7%A2%B3%E8%86%9C%22%5D%20--%3E%20LAW%5B%22%E9%80%9F%E7%8E%87%20%E2%88%9D%20%E8%BE%90%E7%85%A7%E5%BA%A6%20%C3%97%20%E6%9C%89%E6%9C%BA%E5%88%86%E5%8E%8B%22%5D%0A%20%20LAW%20--%3E%20CTRL1%5B%22%E5%87%80%E5%8C%96%20%2B%20%E5%90%B9%E6%89%AB%20%2B%20%E5%85%B3%E5%BF%AB%E9%97%A8%22%5D%0A%20%20PART%5B%22%E9%A2%97%E7%B2%92%E6%B1%A1%E6%9F%93%22%5D%20--%3E%20LAW2%5B%22%E8%BE%93%E8%BF%90%20%2B%20%E9%9D%99%E7%94%B5%E5%90%B8%E9%99%84%EF%BC%8C%E4%B8%8D%E9%9D%A0%E5%85%89%E5%AD%90%22%5D%0A%20%20LAW2%20--%3E%20CTRL2%5B%22%E9%A2%97%E7%B2%92%E8%BF%87%E6%BB%A4%E4%B8%8E%E7%8E%AF%E5%A2%83%E6%B2%BB%E7%90%86%22%5D%0A%20%20CTRL1%20--%3E%20ACCT%5B%22%E4%B8%A4%E6%9D%A1%E8%B4%A6%E5%88%86%E5%BC%80%E8%AE%B0%22%5D%0A%20%20CTRL2%20--%3E%20ACCT%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>工件台干涉仪和编码器的脏是下一单元，不是投影物镜。本课只管投影光路光学面。掩模面上的 haze 是硫酸盐与胺在掩模侧的光化学（<a href="/litho/mask-haze">掩模 haze</a>），账不能记到镜头头上；反过来，镜头碳膜也不该写成激光问题。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>污染是表面光化学，与体致密化分账。</li><li>沉积速率 ∝ 辐照度 × 有机分压，净化与吹扫直接定寿命。</li><li>浸没末片多一条水与析出通道。</li><li>出处：DUV carbon contamination 通识；flare 课。</li></ul>',4))])}const T=s(B,[["render",d]]);export{D as __pageData,T as default};
